INSERT INTO canvases (code, name, created_at, locked) VALUES ('ACME01', 'Experiencia Cliente de ACME', '2026-10-01T09:00:00.000Z', 1);
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00001', 'ACME01', 'proposito', 'Somos el equipo que hace que cada persona que escribe a ACME sienta que alguien se hizo cargo.', '2026-10-01T10:01:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00002', 'ACME01', 'proposito', 'Existimos para que nadie tenga que repetir su problema tres veces: quien lo recibe lo acompaña hasta que se resuelve.', '2026-10-01T10:02:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00003', 'ACME01', 'objetivos', 'A 3 años: ser el área de ACME que más recomienda la gente que compra. Resultado clave: NPS de postventa de 55 o más.', '2026-10-01T10:03:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00004', 'ACME01', 'objetivos', 'Este año: bajar el tiempo de resolución completa sin perder calidad. Resultado clave: 80% de los casos cerrados en 48 horas.', '2026-10-01T10:04:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00005', 'ACME01', 'objetivos', 'Próximos 3 meses: ordenar los reembolsos. Resultado clave: pasar de 9 a 4 días hábiles promedio desde el pedido hasta la acreditación.', '2026-10-01T10:05:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00006', 'ACME01', 'objetivos', 'Próximos 3 meses: sostener el ritmo sin quemarnos. Resultado clave: energía promedio del equipo de 3,5 o más sobre 5 en la medición semanal.', '2026-10-01T10:06:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00007', 'ACME01', 'iniciativas', 'Migración a la herramienta nueva de tickets: cierre de la etapa de ajustes y baja definitiva de la planilla vieja.', '2026-10-01T10:07:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00008', 'ACME01', 'iniciativas', 'Circuito de reembolsos: rediseño del paso a paso con Finanzas, con un solo formulario y un responsable por caso.', '2026-10-01T10:08:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00009', 'ACME01', 'iniciativas', 'Guía de crisis de lanzamientos: qué hacemos desde el primer aviso cuando ACME saca un producto o una promo nueva.', '2026-10-01T10:09:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00010', 'ACME01', 'iniciativas', 'Biblioteca de respuestas vivas: textos base revisados cada mes, con el tono de ACME y espacio para improvisar.', '2026-10-01T10:10:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00011', 'ACME01', 'iniciativas', 'Llamada de cierre: llamar a una muestra de clientes con casos difíciles para preguntarles cómo quedaron.', '2026-10-01T10:11:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00012', 'ACME01', 'personas', 'Marta lidera el equipo, prioriza con Producto y Finanzas y sostiene el foco.', '2026-10-01T10:12:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00013', 'ACME01', 'personas', 'Diego y Lucía atienden los casos de reembolsos y son referentes del circuito nuevo; Lucía además arma los reportes semanales.', '2026-10-01T10:13:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00014', 'ACME01', 'personas', 'Tomás administra la herramienta de tickets (flujos, etiquetas, automatizaciones) y capacita a quien se suma. Valeria coordina los turnos y cobertura de los canales.', '2026-10-01T10:14:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00015', 'ACME01', 'personas', 'Joaquín y Camila atienden por chat y correo los casos de envíos y garantías; Camila además escribe y actualiza la biblioteca de respuestas.', '2026-10-01T10:15:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00016', 'ACME01', 'personas', 'Nico arma el tablero de métricas y facilita las retrospectivas del equipo.', '2026-10-01T10:16:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00017', 'ACME01', 'capacidades', 'Herramienta nueva de tickets: un solo lugar para correos, chat y redes, con etiquetas, plantillas y reglas de asignación automática.', '2026-10-01T10:17:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00018', 'ACME01', 'capacidades', 'Escribir con claridad y calidez en casos tensos, y decir que no sin cerrar la puerta.', '2026-10-01T10:18:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00019', 'ACME01', 'capacidades', 'Leer datos: tablero con tiempo de primera respuesta, tiempo de resolución, reembolsos abiertos y satisfacción por caso.', '2026-10-01T10:19:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00020', 'ACME01', 'capacidades', 'Conocer el producto: catálogo de herramientas, garantías y políticas de devolución, con una guía que se actualiza cada lanzamiento.', '2026-10-01T10:20:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00021', 'ACME01', 'capacidades', 'Trabajo conjunto con Finanzas y Logística: contactos nombrados y una sola vía para escalar.', '2026-10-01T10:21:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00022', 'ACME01', 'principios', 'Quien recibe el caso lo acompaña hasta el final, aunque tenga que pedir ayuda a otras áreas.', '2026-10-01T10:22:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00023', 'ACME01', 'principios', 'Primero entender, después responder: leemos dos veces antes de escribir.', '2026-10-01T10:23:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00024', 'ACME01', 'principios', 'Decimos lo que pasa, incluso cuando es una mala noticia, y avisamos antes de que nos pregunten.', '2026-10-01T10:24:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00025', 'ACME01', 'principios', 'Pedí ayuda temprano: avisar que estás complicado es parte del trabajo.', '2026-10-01T10:25:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00026', 'ACME01', 'acuerdos', 'Reunión de sincro los lunes de 10 a 10:45, con check-in de una palabra y los tres casos más pesados de la semana.', '2026-10-01T10:26:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00027', 'ACME01', 'acuerdos', 'Canales: urgencias del día en el canal del equipo, casos en la herramienta de tickets y nunca por mensaje privado.', '2026-10-01T10:27:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00028', 'ACME01', 'acuerdos', 'Decidimos por consentimiento: se hace una propuesta, se escuchan objeciones y, si nadie tiene una razón fuerte en contra, avanzamos. Marta desempata si no se llega a nada.', '2026-10-01T10:28:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00029', 'ACME01', 'acuerdos', 'Los viernes a la tarde cerramos con un reconocimiento: cada persona cuenta un caso del que se siente orgullosa.', '2026-10-01T10:29:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00030', 'ACME01', 'acuerdos', 'Cada lanzamiento tiene una guardia acordada con tres días de antelación y un descanso compensatorio.', '2026-10-01T10:30:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00031', 'ACME01', 'bienestar', 'Medimos la energía de 1 a 5 cada viernes de forma anónima; quien está en 1 o 2 tiene una charla con Marta esa semana.', '2026-10-01T10:31:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00032', 'ACME01', 'bienestar', 'Después de un día de mucha tensión, nadie atiende más de dos casos difíciles seguidos: se rota con casos livianos.', '2026-10-01T10:32:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00033', 'ACME01', 'bienestar', 'Tras el último lanzamiento acordamos un día de descanso compensatorio y lo respetamos.', '2026-10-01T10:33:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00034', 'ACME01', 'bienestar', 'Pausa real de almuerzo: el canal queda cubierto por turnos y nadie come frente a la pantalla.', '2026-10-01T10:34:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00035', 'ACME01', 'aprendizaje', 'Retrospectiva cada dos meses, con foco en una cosa para empezar, una para dejar y una para seguir.', '2026-10-01T10:35:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00036', 'ACME01', 'aprendizaje', 'Casos de la semana: cada jueves revisamos entre todas una conversación difícil, sin buscar culpables.', '2026-10-01T10:36:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00037', 'ACME01', 'aprendizaje', 'Escuchamos la voz del cliente: leemos juntos los comentarios de las encuestas y elegimos tres cambios por trimestre.', '2026-10-01T10:37:00.000Z');
INSERT INTO notes (id, code, sec, text, at) VALUES ('ACME00038', 'ACME01', 'aprendizaje', 'Aprendimos del lanzamiento tenso: escribimos qué avisos llegaron tarde y los incorporamos a la guía de crisis.', '2026-10-01T10:38:00.000Z');
